type RestoreNodeDevicesRequest struct {
	// TargetNodeId The LIVE gateway the restored devices are homed to. Required rather than defaulted: a revoked gateway is never active again, so there is no sane default, and silently restoring onto the dead node would produce active devices pointing at a gateway that will never serve them.
	TargetNodeId openapi_types.UUID `json:"target_node_id"`
}

// RestoreDevicesResult defines model for RestoreNodeDevicesResponse.
type RestoreDevicesResult struct {
	Devices []struct {
		AssignedIp         string             `json:"assigned_ip"`
		Id                 openapi_types.UUID `json:"id"`
		KeptAddress        bool               `json:"kept_address"`
		Name               string             `json:"name"`
		PreviousAssignedIp *string            `json:"previous_assigned_ip,omitempty"`
	} `json:"devices"`

	// Readdressed How many could NOT reclaim their original address. Each of those users must re-import their config; the device list surfaces it as needs_reexport.
	Readdressed int `json:"readdressed"`

	// Restored How many devices came back.
	Restored int `json:"restored"`
}

// RouteLANRequest defines model for RouteLANRequest.
type RouteLANRequest struct {
	// Cidr The LAN CIDR to route (IPv4). Validated disjoint from the org's other subnets + pool.
	Cidr string `json:"cidr"`

	// Name Optional site name; blank derives a default from the CIDR (S8.5 D1 solo-admin path).
	Name *string `json:"name,omitempty"`

	// NodeId The gateway node that fronts this LAN.
	NodeId openapi_types.UUID `json:"node_id"`
}

// RoutedRanges defines model for RoutedRanges.
type RoutedRanges struct {
	// DialEndpoint WF-A: the device's current dial ENDPOINT (host:port) — the ACTIVE PRIMARY hub's endpoint when the device's assigned node is a hub-set member, so a running device re-homes on promotion. A network fact, not identity. NULL when no device_id was passed, or the device's node is not a hub-set member (it keeps its baked endpoint — the deferred spoke-device case).
	DialEndpoint *string `json:"dial_endpoint"`

	// DialPubkey WF-A: the active-primary hub's WireGuard PUBLIC key — the peer the device swaps to on re-home (a different gateway = a different pubkey; the client does a peer SWAP, not an endpoint update). A public network address, not a secret. NULL under the same conditions as dial_endpoint; always paired with it.
	DialPubkey *string `json:"dial_pubkey"`

	// Forwards DNS forwards whose resolver is REACHABLE via the returned ranges (S8.5 Slice 3). GATED: a forward is included only if its resolver_ip falls inside a routed range — a resolver you can't reach is never handed over (no SERVFAIL generator). Empty when none reachable.
	Forwards []DNSForward `json:"forwards"`

	// Ranges Approved site-subnet CIDRs (canonical masked form, sorted) pushed to split-tunnel device AllowedIPs (S8.5). Ranges only — no identity material. Empty when none declared.
	Ranges []string `json:"ranges"`
}

